"""A least-recently-used cache with optional time-to-live support."""
import time
from collections import OrderedDict


# Sentinel meaning "use the cache default ttl".
class _Default:
    pass


USE_DEFAULT = _Default()


class LRUCache:
    def __init__(self, capacity, ttl=None, clock=time.monotonic):
        if capacity < 1:
            raise ValueError("capacity must be at least 1")
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be greater than 0")
        self.capacity = capacity
        self.ttl = ttl
        self._clock = clock
        # Each entry: [value, stored_at, ttl_for_this_entry]
        self._items = OrderedDict()

    # -- internal helpers -------------------------------------------------

    def _is_expired(self, entry, now=None):
        ttl = entry[2]
        if ttl is None:
            return False
        if now is None:
            now = self._clock()
        return now - entry[1] >= ttl

    def _purge_expired(self):
        now = self._clock()
        expired = [k for k, e in self._items.items() if self._is_expired(e, now)]
        for k in expired:
            del self._items[k]
        return len(expired)

    # -- public API -------------------------------------------------------

    def get(self, key, default=None):
        """Return the value and mark the entry as most recently used.

        Does not restart the entry's lifetime.
        """
        if key not in self._items:
            return default
        entry = self._items[key]
        if self._is_expired(entry):
            del self._items[key]
            return default
        self._items.move_to_end(key)
        return entry[0]

    def peek(self, key, default=None):
        """Return the value without touching the order or lifetime."""
        if key not in self._items:
            return default
        entry = self._items[key]
        if self._is_expired(entry):
            return default
        return entry[0]

    def put(self, key, value, ttl=USE_DEFAULT):
        """Insert or replace an entry.

        ``ttl`` overrides the cache default for this entry. Passing ``None``
        explicitly makes the entry never expire.
        """
        if isinstance(ttl, USE_DEFAULT.__class__):
            entry_ttl = self.ttl
        else:
            entry_ttl = ttl
        if entry_ttl is not None and entry_ttl <= 0:
            raise ValueError("ttl must be greater than 0")

        now = self._clock()

        if key in self._items:
            # Replace: restart lifetime, make most recently used.
            self._items.move_to_end(key)
            self._items[key] = [value, now, entry_ttl]
            return

        # New key. Remove expired entries first so they never cost a live
        # entry its place.
        self._purge_expired()
        if len(self._items) >= self.capacity:
            self._items.popitem(last=False)
        self._items[key] = [value, now, entry_ttl]

    def keys(self):
        """Keys from least to most recently used, excluding expired entries."""
        now = self._clock()
        return [k for k, e in self._items.items() if not self._is_expired(e, now)]

    def __contains__(self, key):
        if key not in self._items:
            return False
        if self._is_expired(self._items[key]):
            return False
        return True

    def __len__(self):
        now = self._clock()
        return sum(1 for e in self._items.values() if not self._is_expired(e, now))
